class Solution:
    def magicalString(self, n: int) -> int:
        if n == 0:
            return 0
        s = [1, 2, 2]
        i, d = 2, 1
        while len(s) < n:
            s.extend([d] * s[i])
            d ^= 3
            i += 1
        return s[:n].count(1)

