class Solution {
public:
    int magicalString(int n) {
        if (n == 0) return 0;
        string s = "122";
        int i = 2;
        char d = '1';
        while ((int)s.size() < n) {
            s.append(s[i] - '0', d);
            d = (d == '1') ? '2' : '1';
            i++;
        }
        return count(s.begin(), s.begin() + n, '1');
    }
};

