    def magicalString(self, n: int) -> int:
        if n == 0:
            return 0
        s = [1, 2, 2]
        i, d, ones, rem = 2, 1, 1, n - 3
        if n <= 3:
            return s[:n].count(1)
        while rem > 0:
            take = min(s[i], rem)
            if d == 1:
                ones += take
            s.extend([d] * take)
            rem -= take
            d ^= 3
            i += 1
        return ones

